const pdfText = $input.first().json.text;

const systemPrompt = `Eres un asistente experto en extraer datos de presupuestos de construccion (contratos de obra) a partir del texto extraido de un PDF.

El PDF contiene el PRESUPUESTO/CONTRATO original de una obra. Debes extraer todas las partidas (items) con sus datos.

Responde UNICAMENTE con un objeto JSON con esta estructura EXACTA:
{
  "proyecto": "Nombre del proyecto",
  "contratista": "Nombre del contratista",
  "fecha": "Fecha del presupuesto",
  "items": [
    {
      "codigo": "Codigo jerarquico (ej: 1, 1.1, 2, 2.3, 2.3.1)",
      "unidad": "Unidad de medida (Ud, M, M2, M3, ML, PA, US, %)",
      "descripcion": "Descripcion completa de la partida",
      "cantidad": 0.00,
      "precio_unitario": 0.00,
      "importe": 0.00
    }
  ],
  "total_presupuesto": 0.00
}

REGLAS:
- codigo: usa el numero de partida exacto del PDF (ej: 1, 1.1, 2.3.1)
- unidad: normaliza a unidades estandar
- cantidad: la cantidad presupuestada
- Las secciones/categorias (como "MEDIOS AUXILIARES", "DEMOLICIONES") extraelas como items con solo codigo y descripcion (sin unidad, cantidad ni precio)
- Extrae TODOS los items, no omitas ninguno
- Los numeros deben ser valores numericos, NO strings
- Si un campo no existe, usa null`;

return [{
  systemPrompt,
  pdfText
}];

const body = $input.first().json.body;
const content = JSON.parse(body.choices[0].message.content);

const rows = [];

// Info del proyecto
rows.push({
  A: 'PROYECTO:',
  B: content.proyecto || ''
});
rows.push({
  A: 'CONTRATISTA:',
  B: content.contratista || ''
});
rows.push({
  A: 'FECHA:',
  B: content.fecha || ''
});
rows.push({});

// Cabeceras
rows.push({
  A: 'Codigo',
  B: 'Ud',
  C: 'Descripcion',
  D: 'CanPres',
  E: 'PrPres',
  F: 'ImpPres'
});

// Items
if (content.items && content.items.length > 0) {
  for (const item of content.items) {
    rows.push({
      A: item.codigo || '',
      B: item.unidad || '',
      C: item.descripcion || '',
      D: item.cantidad ?? '',
      E: item.precio_unitario ?? '',
      F: item.importe ?? ''
    });
  }
}

// Total
rows.push({});
rows.push({
  A: 'TOTAL PRESUPUESTO',
  B: '',
  C: '',
  D: '',
  E: '',
  F: content.total_presupuesto || ''
});

return rows;
